1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives the owner's {@code membershipLevel}, the single loyalty grade the create audit line and the
10	 * owner response both hang off.
11	 *
12	 * <p>The level is built from the owner's own factors: it starts at 1, gains a level for a present
13	 * email address and a level for having no namesakes, with those pre-tenure factors capped at
14	 * {@link #PRE_TENURE_MAX_LEVEL}; the top level ({@link #MAX_MEMBERSHIP_LEVEL}) is reserved for
15	 * tenure and reached only once the owner has more than {@link #TENURE_DAYS_FOR_TOP_LEVEL} days since
16	 * {@code registrationDate}. A freshly created owner registers as of today and so has zero tenure.
17	 */
18	public final class Memberships {
19	
20	    /** The top membership level, reachable only with tenure. */
21	    private static final int MAX_MEMBERSHIP_LEVEL = 4;
22	
23	    /**
24	     * The highest level reachable from the pre-tenure factors alone; the top level
25	     * ({@value #MAX_MEMBERSHIP_LEVEL}) is unlocked only by tenure.
26	     */
27	    private static final int PRE_TENURE_MAX_LEVEL = MAX_MEMBERSHIP_LEVEL - 1;
28	
29	    /**
30	     * Tenure, in days since {@code registrationDate}, that must be exceeded to reach the
31	     * top membership level.
32	     */
33	    private static final int TENURE_DAYS_FOR_TOP_LEVEL = 365;
34	
35	    private Memberships() {
36	    }
37	
38	    /**
39	     * Returns the owner's membership level, a number from 1 to
40	     * {@value #MAX_MEMBERSHIP_LEVEL}: it starts at 1, gains 1 when an email address is
41	     * present, gains 1 when the owner has no namesakes (namesakeCount is 0), and these
42	     * pre-tenure factors are capped at {@value #PRE_TENURE_MAX_LEVEL}. Level
43	     * {@value #MAX_MEMBERSHIP_LEVEL} is reserved for tenure: it is reached only when the
44	     * owner has more than {@value #TENURE_DAYS_FOR_TOP_LEVEL} days of tenure. A newly
45	     * created owner registers as of the current day and so has zero tenure, meaning a new
46	     * owner never exceeds level {@value #PRE_TENURE_MAX_LEVEL}.
47	     */
48	    public static int membershipLevel(Owner owner) {
49	        int level = 1;
50	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
51	        if (hasEmail) {
52	            level++;
53	        }
54	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
55	        if (noNamesakes) {
56	            level++;
57	        }
58	        // Level 4 is reserved for tenure: cap the pre-tenure factors, then let more than
59	        // TENURE_DAYS_FOR_TOP_LEVEL days of tenure unlock the top level.
60	        level = Math.min(level, PRE_TENURE_MAX_LEVEL);
61	        if (hasTopLevelTenure(owner)) {
62	            level++;
63	        }
64	        return level;
65	    }
66	
67	    /**
68	     * True when the owner's tenure (days between {@code registrationDate} and today)
69	     * exceeds {@value #TENURE_DAYS_FOR_TOP_LEVEL}. An owner with no registration date
70	     * (e.g. legacy seed owners) has no tenure.
71	     */
72	    private static boolean hasTopLevelTenure(Owner owner) {
73	        LocalDate registrationDate = owner.getRegistrationDate();
74	        if (registrationDate == null) {
75	            return false;
76	        }
77	        long tenureDays = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
78	        return tenureDays > TENURE_DAYS_FOR_TOP_LEVEL;
79	    }
80	}
