204	    /**
205	     * Return the Pet with the given name, or null if none found for this Owner.
206	     *
207	     * @param name to test
208	     * @return true if pet name is already in use
209	     */
210	    public Pet getPet(String name) {
211	        return getPet(name, false);
212	    }
213	
214	    /**
215	     * Return the Pet with the given name, or null if none found for this Owner.
216	     *
217	     * @param name to test
218	     * @return true if pet name is already in use
219	     */
220	    public Pet getPet(String name, boolean ignoreNew) {
221	        name = name.toLowerCase();
222	        for (Pet pet : getPetsInternal()) {
223	            if (!ignoreNew || !pet.isNew()) {
224	                String compName = pet.getName();
225	                compName = compName.toLowerCase();
226	                if (compName.equals(name)) {
227	                    return pet;
228	                }
229	            }
230	        }
231	        return null;
232	    }
233	
234	    public Pet getPet(Integer petId) {
235	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
236	    }
237	
238	    @Override
239	    public String toString() {
240	        return new ToStringCreator(this)
241	
242	            .append("id", this.getId())
243	            .append("new", this.isNew())
244	            .append("lastName", this.getLastName())
245	            .append("firstName", this.getFirstName())
246	            .append("address", this.address)
247	            .append("city", this.city)
248	            .append("telephone", this.telephone)
249	            .toString();
250	    }
251	}
