18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "membershipLevel",
40	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Memberships.membershipLevel(owner))")
41	    @Mapping(target = "locality", expression = "java(locality(owner))")
42	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
43	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
44	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
45	    @Mapping(target = "identityKey",
46	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
47	    @Mapping(target = "telephoneDisplay",
48	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
49	    public abstract OwnerDto toOwnerDto(Owner owner);
50	
51	    /**
52	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
53	     * present (non-null and non-blank), otherwise {@code PHONE}.
54	     */
55	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
57	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
58	    }
59	
60	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
61	    private static final int ADULT_AGE = 18;
62	
63	    /** The age (in years) at which an owner becomes a senior. */
64	    private static final int SENIOR_AGE = 65;
65	
66	    /**
67	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
68	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
69	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
70	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
71	     * either the birth date or the registration date is absent, so an owner created
72	     * without a birth date has no age band.
73	     */
74	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
75	        LocalDate birthDate = owner.getBirthDate();
76	        LocalDate registrationDate = owner.getRegistrationDate();
77	        if (birthDate == null || registrationDate == null) {
78	            return null;
79	        }
80	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
81	        if (age < ADULT_AGE) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (age < SENIOR_AGE) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
89	
90	    /**
91	     * Derives the owner's {@code locality} (canonical region string) from the
92	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
93	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
94	     * fall back to deriving the region directly from postcode, then city, then
95	     * {@code "UNKNOWN"}.
96	     */
97	    protected String locality(Owner owner) {
98	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
99	                .regionOf(owner.getCustomerCode());
100	        if (region != null) {
101	            return region;
102	        }
103	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
104	    }
105	
106	    /**
107	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
108	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
109	     * customer code or the registration date is absent (e.g. legacy seed owners).
110	     */
111	    protected String membershipNumber(Owner owner) {
112	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
113	            return null;
114	        }
115	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
116	    }
117	
118	    /**
119	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
120	     * been created for this owner's {@code registrationDate}, using the same per-day
121	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
122	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
123	     */
124	    protected boolean bulkSignupWarning(Owner owner) {
125	        LocalDate registrationDate = owner.getRegistrationDate();
126	        if (registrationDate == null) {
127	            return false;
128	        }
129	        long count = ownerRepository.findAll().stream()
130	                .filter(existing -> !existing.getId().equals(owner.getId()))
131	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
132	                .count();
133	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
134	    }
135	
136	    /**
137	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
138	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
139	     * legacy seed owners).
140	     */
141	    protected Integer checkDigit(Owner owner) {
142	        String customerCode = owner.getCustomerCode();
143	        if (customerCode == null) {
144	            return null;
145	        }
146	        int sum = 0;
147	        boolean dbl = true;
148	        for (int i = customerCode.length() - 1; i >= 0; i--) {
149	            char c = customerCode.charAt(i);
150	            if (c < '0' || c > '9') {
151	                continue;
152	            }
153	            int d = c - '0';
154	            if (dbl) {
155	                d *= 2;
156	                if (d > 9) {
157	                    d -= 9;
158	                }
159	            }
160	            sum += d;
161	            dbl = !dbl;
162	        }
163	        return (10 - (sum % 10)) % 10;
164	    }
165	
166	    public abstract Owner toOwner(OwnerDto ownerDto);
167	
168	    @Mapping(target = "id", ignore = true)
169	    @Mapping(target = "pets", ignore = true)
170	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
171	
172	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
173	
174	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
175	
176	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
177	        OwnerPageDto ownerPageDto = new OwnerPageDto();
178	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
179	        ownerPageDto.setPage(ownerPage.getNumber());
180	        ownerPageDto.setSize(ownerPage.getSize());
181	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
182	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
183	        return ownerPageDto;
184	    }
185	}
