9	/**
10	 * Derives the deterministic {@code householdId}: the first 12 hex characters of
11	 * {@code SHA-256(normalizedLastName + '|' + postcode)}.
12	 *
13	 * <p>Because it depends only on the last name and postcode, every owner sharing those two values
14	 * resolves to the same id automatically, without any request opting in and without back-filling
15	 * other members. The last name is normalized case-insensitively with runs of whitespace collapsed;
16	 * the postcode is trimmed and contributes an empty segment when absent.
17	 */
18	public final class Households {
19	
20	    private Households() {
21	    }
22	
23	    /** The householdId for the owner, derived from its last name and postcode. */
24	    public static String id(Owner owner) {
25	        return id(owner.getLastName(), owner.getPostcode());
26	    }
27	
28	    /** The householdId for the given last name and postcode. */
29	    public static String id(String lastName, String postcode) {
30	        String input = normalize(lastName) + '|' + segment(postcode);
31	        try {
32	            byte[] digest = MessageDigest.getInstance("SHA-256")
33	                    .digest(input.getBytes(StandardCharsets.UTF_8));
34	            StringBuilder sb = new StringBuilder(12);
35	            for (int i = 0; i < 6; i++) {
36	                sb.append(String.format("%02x", digest[i]));
37	            }
38	            return sb.toString();
39	        }
40	        catch (NoSuchAlgorithmException e) {
41	            throw new IllegalStateException("SHA-256 not available", e);
42	        }
43	    }
44	
45	    private static String normalize(String value) {
46	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
47	    }
48	
49	    private static String segment(String value) {
50	        return value == null ? "" : value.trim();
51	    }
52	}
