138	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
139	     * legacy seed owners).
140	     */
141	    protected Integer checkDigit(Owner owner) {
142	        String customerCode = owner.getCustomerCode();
143	        if (customerCode == null) {
144	            return null;
145	        }
146	        int sum = 0;
147	        boolean dbl = true;
148	        for (int i = customerCode.length() - 1; i >= 0; i--) {
